            archetypeSignatureName: '시그니처',
            archetypeSignatureTagline: '로마 숫자 부, 번호가 매겨진 장, 섹션 구분.',
            blurbSubmission: '6×9 페이지에 산세리프 서체, 1.5 줄 간격, 별도의 장면 시작 페이지를 갖춘 단순한 읽기용 초고입니다. 독자에 맞게 판형과 타이포그래피를 사용자 지정하세요.',
            blurbReadingDraft: '베타 리더와 교정자를 위한 다듬어진 읽기용 초고입니다. 최종 미적 방향을 정하지 않고도 완성된 책처럼 느껴질 만큼 깔끔합니다. 현대적인 세리프 본문 서체, 편안한 간격, 현대 상업 소설에 익숙한 절제된 구조를 갖추었습니다.',
            blurbLiterary: '세련되고 출판을 염두에 둔 스타일로, 전문적으로 조판된 단행본 소설의 느낌을 줍니다. 러닝 헤드, 체계적인 장 표현, 더 강한 시각적 리듬이 절제되고 읽기 쉬운 상태를 유지하면서도 더 몰입감 있는 독서 경험을 만듭니다.',
            blurbStructured: '건축적이고 문학적입니다. 의도적인 페이싱, 구조적 여백, 막 시작 페이지, 에피그래프, 개성 있는 장면 표현이 어울리는 야심 찬 소설을 위해 만들어졌습니다. 부티크 문학 판본과 20세기 중반 인쇄 디자인 전통의 공들인 장인 정신을 떠올리게 합니다.',
            notePage: '페이지 크기와 여백은 대부분의 작가가 생각하는 것보다 독서 경험에 더 큰 영향을 줍니다. 촘촘한 레이아웃은 밀도와 속도감을 높이고, 넓은 여백은 시각적 여유와 더 문학적인 느낌을 만듭니다. 대부분의 상업 소설은 가독성과 효율적인 페이지 수 사이에서 균형을 맞춥니다.',
            noteBody: '본문 타이포그래피는 긴 글을 읽을 때의 편안함을 좌우합니다. 세리프 서체는 빽빽한 텍스트 페이지에서 시선을 자연스럽게 이끌기 때문에 인쇄 소설에서 여전히 주류입니다. 줄 간격은 속도감에 미묘하게 영향을 줍니다. 촘촘한 레이아웃은 더 빠르고 긴박하게 느껴지고, 넓은 간격은 독자의 속도를 늦추고 사색을 유도합니다.',
            noteHeaders: '러닝 헤더는 긴 작품에서 독자가 위치를 파악하는 데 도움이 되며 완성된 인쇄본에서 흔히 사용됩니다. 원고 초안에서는 보통 완전히 생략하지만, 다듬어진 단행본 및 문학 레이아웃에서는 본문을 방해하지 않으면서 구조를 강조하는 절제된 머리글을 자주 사용합니다.',
            noteFolio: '쪽 번호는 원고 안에서 독자의 위치를 조용히 잡아 줍니다. 전통적인 초안은 보통 쪽 번호를 하단 가운데에 두지만, 출간된 소설은 더 세련된 표현을 위해 러닝 헤더 체계에 통합하는 경우가 많습니다.',
            noteParts: '부 페이지는 주요 서사 흐름을 나누고 막이나 이야기 단계 사이에 구조적 여유를 만듭니다. 문학 소설과 대규모 상업 소설은 주제 전환과 긴 호흡의 추진력을 강화하기 위해 전용 부 시작 페이지, 로마 숫자 또는 에피그래프를 자주 사용합니다.',
            noteChapters: '장 표현은 서사의 리듬을 형성합니다. 최소한의 장 페이지는 속도감을 눈에 띄지 않게 빠르게 유지하고, 큰 시작 페이지는 멈춤, 강조, 기대감을 만듭니다. 공통 장 제목과 시작 페이지 간격은 분위기와 장르적 기대를 미묘하게 강화할 수 있습니다.',
            noteScenes: '장면 구분은 미시적 수준에서 추진력을 조절합니다. 보이지 않는 전환은 속도감과 연속성을 만들고, 전용 장면 시작 페이지는 각 시퀀스에 감정적 또는 구조적 무게를 부여합니다. 번호, 제목, 장식 선은 복잡한 서사 속에서 독자가 방향을 잡도록 돕습니다.',
            noteEpigraph: '에피그래프는 본문이 시작되기 전에 섹션의 감정적 또는 주제적 렌즈를 설정합니다. 어떤 소설은 강조를 위해 아껴서 사용하고, 문학 소설과 구조적 소설은 반복되는 에피그래프로 막, 장, 캐릭터 아크 전반에 울림을 만들기도 합니다.',
