            recoveryFilesTitle: '복구 파일이 Logs 밖으로 이동됨',
            recoveryFilesDescription: '스냅샷과 Gossamer Archive(삭제되거나 덮어쓴 노트 데이터를 복구하는 데 쓰이는 파일)는 이제 Radial Timeline/Logs 대신 Radial Timeline/Recover 아래에 있습니다. 이제 Logs 폴더에는 지워도 되는 실행 로그만 있으므로, 복구 데이터를 잃지 않고 언제든지 비울 수 있습니다. 이번 업데이트 이전의 폴더가 Radial Timeline/Logs/Snapshots 또는 Radial Timeline/Logs/Gossamer Archive에 아직 있다면, 이전 복구 데이터를 보존하기 위해 해당 폴더를 Radial Timeline/Recover로 옮기세요. 경고: Radial Timeline/Snapshots는 옮기지 마세요 — 이 폴더는 Timeline Repair가 타임라인을 복원할 때 읽는, 현재 사용 중인 다른 폴더이며 옮기면 복원 기능이 작동하지 않습니다.',
            inquiryProButtonsTitle: 'Inquiry Pro 버튼 스타일 변경',
